export const title = "How to Plan a Printer Station on a Small Shelf or Rolling Cart";
export const metaTitle = "How to Plan a Printer Station on a Small Shelf";
export const metaDescription = "Plan printing and service, not just storage. Practical measurements, original diagrams and fit checks for office equipment in small workspaces.";
export const author = "Jamie Cole, Lead Product Researcher";
